p='calendar/index.html'; s=open(p).read()
a='''    <!-- rightmost: the hamburger, and the way out -->
    <div class="tb-side end">
      <button id="menu-btn" class="nav ic" aria-label="Filter and settings"
              aria-haspopup="true" aria-expanded="false"></button>'''
b='''    <!-- rightmost: the filter, the hamburger, and the way out -->
    <div class="tb-side end">
      <button id="filter-btn" class="nav ic" aria-label="Filter"
              aria-haspopup="true" aria-expanded="false"></button>
      <button id="menu-btn" class="nav ic" aria-label="Settings and logs"
              aria-haspopup="true" aria-expanded="false"></button>'''
assert a in s; s=s.replace(a,b)
a='''<!-- the hamburger's three errands, named before any is opened -->'''
b='''<!-- the hamburger's two errands, named before either is opened -->'''
assert a in s; s=s.replace(a,b)
a='''<!-- the filter: a dropdown off the hamburger, because the view it narrows has to stay in sight -->'''
b='''<!-- the filter: a dropdown off its own button, because the view it narrows has to stay in sight -->'''
assert a in s; s=s.replace(a,b)
open(p,'w').write(s)

p='calendar/settings.js'; s=open(p).read()
a='''export function openFilter() {
  closePops();
  renderFilter();
  openPop($('#filter-pop'), $('#menu-btn'), 'right');
}'''
b='''export function openFilter() {
  if (!$('#filter-pop').hidden) return closePops();
  closePops();
  renderFilter();
  openPop($('#filter-pop'), $('#filter-btn'), 'right');
}'''
assert a in s; s=s.replace(a,b)
a='''export function renderFilterCount() {
  const n = filterCount();
  $('#menu-btn').querySelector('.fcount')?.remove();
  $('#menu-btn').setAttribute('aria-label',
    n ? `Filter and settings — ${n} filter${n > 1 ? 's' : ''} on` : 'Filter and settings');
  if (n) $('#menu-btn').append(el('span', 'fcount', String(n)));
}'''
b='''export function renderFilterCount() {
  const n = filterCount();
  $('#filter-btn').querySelector('.fcount')?.remove();
  $('#filter-btn').setAttribute('aria-label',
    n ? `Filter — ${n} filter${n > 1 ? 's' : ''} on` : 'Filter');
  if (n) $('#filter-btn').append(el('span', 'fcount', String(n)));
}'''
assert a in s; s=s.replace(a,b)
a='''// A filter that is on says so on the hamburger, which is otherwise the one button in the pane
// that looks the same whatever it is doing.'''
b='''// A filter that is on says so on the filter's own button, which otherwise looks the same
// whatever it is doing.'''
assert a in s; s=s.replace(a,b)
a='''// The hamburger's three errands, each its own overlay. The filter is a dropdown off the hamburger,
// because it is the half you open often and the view it narrows has to stay in sight while you
// narrow it;'''
b='''// The filter, and the hamburger's two errands, each its own overlay. The filter is a dropdown off
// its own button in the pane, because it is the one you open often and the view it narrows has to
// stay in sight while you narrow it;'''
assert a in s; s=s.replace(a,b)
open(p,'w').write(s)

p='calendar/app.js'; s=open(p).read()
reps=[("""for (const [id, name] of [['#home', 'house'], ['#search-btn', 'search'], ['#menu-btn', 'menu'],""",
"""for (const [id, name] of [['#home', 'house'], ['#search-btn', 'search'], ['#filter-btn', 'filter'],
  ['#menu-btn', 'menu'],"""),
("""// ---- the hamburger's menu ------------------------------------------------------------------
// Three errands behind one button, each named before it is opened and each opening on its own.
// The first two used to open at once in a single panel, where a heading was the only thing
// telling a group you hide this afternoon from the week's first day, and the filter had no room
// to list its groups without pushing the settings off the screen.
//
// The third is the one you reach for when the sync line says something you did not expect: what
// the last attempt did, what is still waiting, and the two ways out of it.
const MENU = [['filter', 'filter', openFilter], ['gear', 'settings', openPanel],
  ['logs', 'logs', openLogs]];""",
"""// ---- the filter, and the hamburger's menu --------------------------------------------------
// The filter has a button of its own in the pane: it is opened daily, and a menu in front of it
// was a tap spent naming the one errand you came for. The hamburger keeps the two you open
// rarely, each named before it is opened - the settings, and the logs, which you reach for when
// the sync line says something you did not expect.
const MENU = [['gear', 'settings', openPanel], ['logs', 'logs', openLogs]];"""),
("""$('#menu-btn').addEventListener('click', openMenu);""","""$('#menu-btn').addEventListener('click', openMenu);
$('#filter-btn').addEventListener('click', openFilter);"""),
]
for a,b in reps:
    assert a in s, a; s=s.replace(a,b)
open(p,'w').write(s)
EOF
git grep -n "menu-btn\|openFilter" calendar/ | grep -v "^calendar/index.html"

